    @tracer.start_as_current_span("contants.rapi_getUserPbxInfo")
    @api_version_check(min_version=107)
    def rapi_getUserPbxInfo(self, sn: str) -> dict:
        """
        Получить информацию о PBX-биндингах пользователя (телефонные номера)
        Возвращает список PBX-биндингов пользователя. Сейчас это его телефонные номера, в будущем - типы номеров и т.д.
        Если список пустой, то биндингов нет.
        :param sn: Уникальный идентификатор пользователя внутри сервиса
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/getUserPbxInfo",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"sn": sn},
            },
        )

    @tracer.start_as_current_span("contants.rapi_contacts_counter")
    @api_version_check(min_version=105)
    def rapi_contacts_counter(self, sn: str, enable: bool = False) -> dict:
        """
        Управление каунтером чата
        Позволяет пользователю учитывать/не учитывать количество непрочитанных сообщений выбранного контакта или
        группы в общем количестве непрочитанных
        :param sn: Уникальный идентификатор пользователя внутри сервиса
        :param enable: false - счётчик чата не учитывается в общем количестве непрочитанных
        true - счётчик чата учитывается в общем количестве непрочитанных
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/contacts/counter",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"sn": sn, "enable": enable},
            },
        )
